{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C22"],
      "claim": "Tazemetostat, the closest analogue (Morgan 0.277), has a measured human absolute oral bioavailability of 33.9% and shares the hydroxyamidine and morpholine-containing heteroaromatic features with the query, supporting F >= 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C32"],
      "claim": "Entrectinib, a moderately similar analogue (Morgan 0.25), has reported human oral bioavailability >50% and shares azole, morpholine, and aromatic amine motifs, supporting high oral bioavailability.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C27"],
      "claim": "Mebendazole, a benzimidazole analogue with very low human bioavailability (~1%), is contradictory, but its lack of the ionizable morpholine and hydroxyamidine groups and its very low solubility limit transferability to the query.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The closest and most mechanistically relevant analogues with human absolute bioavailability data, tazemetostat (33.9%) and entrectinib (>50%), support F >= 20%. Low-bioavailability benzimidazole carbamates are less transferable because they lack the solubilizing morpholine and hydroxyamidine groups present in the query.",
  "evidence_gaps": [
    "No direct bioavailability measurement exists for the query molecule; all analogues have Morgan similarity below 0.28.",
    "Some retrieved records appear to have compound-name/SMILES mismatches (e.g., fenofibrate/fenbendazole, R406), so those records were not weighted.",
    "Human absolute bioavailability data are available for tazemetostat and entrectinib, but not for a compound with the exact benzimidazole-pyrazole-hydroxyamidine combination."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

